/**
 * Prototype flow registry
 *
 * Add an entry here for every flow you create under app/prototypes/<slug>/.
 * The index page reads from this list — no other wiring needed.
 */

export type FlowMeta = {
  slug: string
  name: string
  description: string
  /** What the flow exercises in the design system */
  exercises: string[]
  /** Optional tag — "in-progress" | "stable" | "experimental" */
  status?: "in-progress" | "stable" | "experimental"
}

export const flows: FlowMeta[] = []

"use client"
import { ArrowDown, ArrowUp, Minus } from "lucide-react"
import { Alert } from "@atlas/ui-web/compositions/Alert/Alert"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import { Badge } from "@atlas/ui-web/primitives/Badge/Badge"
import { Skeleton } from "@atlas/ui-web/primitives/Skeleton/Skeleton"
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@atlas/ui-web/compositions/Card/Card"
import {
  Chart, ChartBar, ChartContent, ChartDescription, ChartHeader, ChartTitle,
} from "@atlas/ui-web/compositions/Chart/Chart"
import {
  ListItem, ListItemActions, ListItemContent, ListItemDescription, ListItemTitle,
} from "@atlas/ui-web/compositions/ListItem/ListItem"
import {
  GREETING_NAME, SPENDING_7_DAYS, SUMMARIES, TRANSACTIONS, formatMoney,
  type DashboardStatus, type Summary,
} from "../data"

const column = { display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-4)" } as const
const pad = { paddingInline: "var(--atlas-spacing-4)", paddingBlockEnd: "var(--atlas-spacing-6)" } as const

function Change({ s }: { s: Summary }) {
  const dir = s.change > 0 ? "up" : s.change < 0 ? "down" : "unchanged"
  const good = s.change === 0 ? null : (s.change > 0) === s.upIsGood
  const Icon = s.change > 0 ? ArrowUp : s.change < 0 ? ArrowDown : Minus
  const text = s.change === 0 ? "No change" : `${Math.abs(s.change)}%`
  return (
    <Badge
      size="sm"
      variant={good === null ? "neutral" : good ? "success" : "danger"}
      leadingIcon={<Icon size={12} aria-hidden="true" />}
    >
      <span>{text}</span>
      <span style={{ position: "absolute", width: 1, height: 1, overflow: "hidden", clip: "rect(0 0 0 0)" }}>
        {` ${dir} since last month`}
      </span>
    </Badge>
  )
}

function SummaryGrid() {
  return (
    <ul
      aria-label="Account summary"
      style={{ listStyle: "none", margin: 0, padding: 0, display: "grid", gridTemplateColumns: "1fr 1fr", gap: "var(--atlas-spacing-3)" }}
    >
      {SUMMARIES.map((s) => (
        <li key={s.key}>
          <Card variant="outlined" size="sm">
            <CardContent>
              <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-1)" }}>
                <span style={{ fontSize: "var(--atlas-text-caption)", color: "var(--atlas-foreground-muted)" }}>{s.label}</span>
                <span style={{ fontSize: "var(--atlas-font-size-xl)", fontWeight: "var(--atlas-font-weight-semibold)", color: "var(--atlas-foreground)" }}>
                  {formatMoney(s.value)}
                </span>
                <div><Change s={s} /></div>
              </div>
            </CardContent>
          </Card>
        </li>
      ))}
    </ul>
  )
}

function SpendingChart() {
  return (
    <Chart>
      <ChartHeader>
        <ChartTitle>Spending, last 7 days</ChartTitle>
        <ChartDescription>Daily spending from Thursday to Wednesday.</ChartDescription>
      </ChartHeader>
      <ChartContent>
        <ChartBar
          aria-label="Bar chart of daily spending over the last 7 days"
          data={SPENDING_7_DAYS}
          xKey="day"
          dataKey="amount"
          label="Spending"
        />
      </ChartContent>
    </Chart>
  )
}

function Activity() {
  return (
    <Card variant="outlined">
      <CardHeader><CardTitle as="h2">Recent activity</CardTitle></CardHeader>
      <CardContent>
        <ul style={{ listStyle: "none", margin: 0, padding: 0, display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-1)" }}>
          {TRANSACTIONS.map((t) => (
            <ListItem key={t.id} as="li" variant="default" size="md">
              <ListItemContent>
                <ListItemTitle>{t.name}</ListItemTitle>
                <ListItemDescription>{`${t.category} · ${t.date}`}</ListItemDescription>
              </ListItemContent>
              <ListItemActions>
                <span
                  style={{
                    fontSize: "var(--atlas-text-body-sm)",
                    fontWeight: "var(--atlas-font-weight-semibold)",
                    color: t.amount > 0 ? "var(--atlas-success)" : "var(--atlas-foreground)",
                  }}
                >
                  {t.amount > 0 ? "+" : "−"}{formatMoney(Math.abs(t.amount))}
                </span>
              </ListItemActions>
            </ListItem>
          ))}
        </ul>
      </CardContent>
    </Card>
  )
}

function LoadingView() {
  const row = (w: string, h?: string) => <Skeleton style={{ width: w, height: h }} />
  return (
    <div aria-busy="true" aria-label="Loading your dashboard" role="status" style={column}>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "var(--atlas-spacing-3)" }}>
        {SUMMARIES.map((s) => (
          <Card key={s.key} variant="outlined" size="sm">
            <CardContent>
              <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-2)" }}>
                {row("50%")}{row("80%", "var(--atlas-spacing-6)")}{row("40%")}
              </div>
            </CardContent>
          </Card>
        ))}
      </div>
      <Chart state="loading">
        <ChartHeader>
          <ChartTitle>Spending, last 7 days</ChartTitle>
        </ChartHeader>
        <ChartContent loadingLabel="Loading spending chart" />
      </Chart>
      <Card variant="outlined">
        <CardContent>
          <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-3)" }}>
            {[0, 1, 2, 3, 4].map((i) => (
              <div key={i} style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-1)" }}>
                {row("60%")}{row("40%", "var(--atlas-spacing-3)")}
              </div>
            ))}
          </div>
        </CardContent>
      </Card>
    </div>
  )
}

export function Dashboard({ status, onRetry }: { status: DashboardStatus; onRetry: () => void }) {
  return (
    <div style={{ ...column, ...pad }}>
      <header style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-1)" }}>
        <h1 style={{ margin: 0, fontSize: "var(--atlas-text-h1)", fontWeight: "var(--atlas-font-weight-bold)", color: "var(--atlas-foreground)", lineHeight: "var(--atlas-line-height-tight)" }}>
          Dashboard
        </h1>
        <p style={{ margin: 0, fontSize: "var(--atlas-text-body)", color: "var(--atlas-foreground-muted)" }}>
          Good morning, {GREETING_NAME}. Here&rsquo;s your month so far.
        </p>
      </header>

      {status === "loading" && <LoadingView />}

      {status === "failed" && (
        <Alert
          variant="danger"
          size="md"
          title="We couldn't load your dashboard"
          description="This looks like a connection problem. Your accounts are safe. Try again in a moment."
          actions={<Button size="sm" variant="primary" onClick={onRetry}>Try again</Button>}
        />
      )}

      {status === "loaded" && (
        <>
          <SummaryGrid />
          <SpendingChart />
          <Activity />
        </>
      )}
    </div>
  )
}
